#pragma once
// Random-forest inference over the arrays in model.h (generated by tools/export_model.py).

#include "wb_features.h"
#include "model.h"

namespace wb {

// Returns the predicted class index (see CLASS_NAMES in model.h).
inline int predict(const float features[NFEAT]) {
  int votes[NUM_CLASSES] = {0};
  for (int t = 0; t < NUM_TREES; t++) {
    uint16_t n = TREE_ROOT[t];
    while (TREE_FEATURE[n] >= 0) {
      n = (features[TREE_FEATURE[n]] <= TREE_THRESH[n]) ? TREE_LEFT[n] : TREE_RIGHT[n];
    }
    votes[TREE_LEFT[n]]++;       // for a leaf, TREE_LEFT holds the class index
  }
  int best = 0;
  for (int c = 1; c < NUM_CLASSES; c++) {
    if (votes[c] > votes[best]) best = c;
  }
  return best;
}

}  // namespace wb
